{"code":"import pandas as pd

def debug_silence_extraction(session):
    events = pd.read_csv(f'sub-0_ses-{session}_events.tsv', sep='\t')
    ev = events.sort_values('timemeg').reset_index(drop=True)
    # print first phoneme word-onsets and preceding event
    print(f"Session {session} samples:")
    count=0
    for i,row in ev.iterrows():
        if row['kind']=='phoneme' and row['phonemeidx']==1:
            prev = ev.loc[i-1] if i>0 else None
            print(f"Idx {row.name}: phoneme idx1 at t={row.timemeg}, prev kind={(prev['kind'] if prev is not None else None)}, duration={(prev['duration'] if prev is not None else None)}")
            count+=1
            if count>=5:
                break

# Debug first two sessions
for sess in [1,2]:
